<?php
$historyStart=$checks;
$nativeBefore=$campaignStore->analyticsOverview(audienceAnalyticsWindow([]))['totals'];
$jobsBefore=$conn->query('SELECT COUNT(*) FROM marketing_campaign_deliveries')->fetch_row()[0];
$contactBefore=$conn->query("SELECT GROUP_CONCAT(CONCAT(id,':',email_status) ORDER BY id) FROM marketing_contacts WHERE audience_id=1")->fetch_row()[0];
$csv=str_replace('Thursday, October 15, 2026 at 9:01 AM',(new DateTimeImmutable('now',new DateTimeZone('America/Chicago')))->modify('-2 days')->setTime(9,1)->format('l, F j, Y \a\t g:i A'),file_get_contents(__DIR__.'/fixtures/mailchimp-history/campaign.csv'));$report=audienceMailchimpReport($csv,'America/Chicago','filtered');$report['provenance']['source_audience']='Original example audience';$hash=hash('sha256',$csv);
$import=new AudienceStore($conn,1,$actorId,'History fixture');
$preview=$import->importMailchimpHistory([$report],$hash,'fixture.csv');
audienceHttpExpect($preview['added']===1&&!$preview['applied']&&(int)$import->mailchimpHistorySummary()['campaigns']===0,'History dry run validates without adding a record');
$applied=$import->importMailchimpHistory([$report],$hash,'fixture.csv',true);audienceHttpExpect($applied['added']===1&&$applied['applied'],'History applies the validated summary only');
$again=$import->importMailchimpHistory([$report],$hash,'fixture.csv',true);audienceHttpExpect($again['unchanged']===1&&(int)$import->mailchimpHistorySummary()['campaigns']===1,'Repeated bundle import is idempotent');
$updated=audienceMailchimpReport(str_replace('196 (20%)','197 (20.1%)',$csv),'America/Chicago','filtered');
$updated['provenance']['source_audience']='Original example audience';
audienceHttpExpect($import->importMailchimpHistory([$updated],hash('sha256','new'), 'updated.csv',true)['updated']===1,'A later export updates lifetime counts instead of duplicating a campaign');
$other=audienceMailchimpReport(str_replace('Example community update','Another community update',$csv),'America/Chicago','unknown');
$failed=false;try{$import->importMailchimpHistory([$other,$report,$updated],$hash,'conflict.csv',true);}catch(InvalidArgumentException){$failed=true;}
audienceHttpExpect($failed&&(int)$import->mailchimpHistorySummary()['campaigns']===1,'Conflicting identities roll back the entire import');
$historyWindow=audienceAnalyticsWindow(['origin'=>'mailchimp']);$historical=$import->analyticsOverview($historyWindow);
audienceHttpExpect($historical['totals']['accepted']===1000&&$historical['totals']['opens']===197&&array_sum(array_column($historical['daily'],'accepted'))===1000,'History headline and daily cohort totals reconcile');
audienceHttpExpect($historical['totals']['click_rate']===5.0&&$historical['totals']['delivery_rate']===98.0,'Source-specific rate denominators are preserved');
audienceHttpExpect($import->analyticsOverview(array_replace($historyWindow,['start'=>'2020-01-01','end'=>'2020-01-30','from'=>'2020-01-01 00:00:00','until'=>'2020-01-31 00:00:00']))['totals']['open_rate']===null,'Missing historical observations remain unknown');
audienceHttpExpect((int)$as->mailchimpHistorySummary()['campaigns']===0,'Historical summaries never cross audience boundaries');
audienceHttpExpect($campaignStore->analyticsOverview(audienceAnalyticsWindow([]))['totals']===$nativeBefore,'Historical summaries do not fabricate native delivery cohorts');
$evidence=audienceAiEvidence($historical,$historyWindow);audienceHttpExpect($evidence['facts'][0]['value']===1000&&str_contains($evidence['calculations']['open_rate'],'successful deliveries')&&$evidence['window']['origin']==='mailchimp','Analytics AI uses the exact selected historical source and formulas');
audienceHttpExpect(!str_contains(json_encode($evidence),'example.test')&&!str_contains(json_encode($evidence),'Example community'),'Historical AI scope excludes campaign subjects, links and contacts');
$page=$admin('audience.php?view=analytics&section=history');audienceHttpExpect($page['status']===200&&str_contains($page['body'],'Historical email performance')&&str_contains($page['body'],'Example community update')&&!preg_match('/(?:Warning|Fatal error):/',$page['body']),'History route renders the retained source and native date controls');
audienceHttpExpect(str_contains($page['body'],'origin=mailchimp')&&str_contains($page['body'],'Ask Analytics AI'),'History AI navigation preserves its source');
$export=$editor('audience.php?view=analytics&section=history&download=csv');audienceHttpExpect($export['status']===200&&str_contains($export['body'],'Mailchimp reported sends')&&str_contains($export['body'],'Mailchimp exported summary'),'History export identifies campaign-cohort dates and source');
audienceHttpExpect($reviewer('audience.php?view=analytics&section=history&download=csv')['status']===403,'Reviewer cannot export historical reports');
audienceHttpExpect($admin('audience.php?view=analytics&section=history&channel=automation')['status']===400,'Unsupported historical email-type filtering is explicit');
audienceHttpExpect($admin('audience.php?view=analytics&section=history&segment=1')['status']===400,'Current recipient segments cannot be misrepresented as historical membership');
audienceHttpExpect($admin('audience.php?view=home&origin=mailchimp')['status']===303,'Historical Home links canonicalize to the source-specific dashboard');
$assistant=$admin('audience.php?view=assistant&mode=analytics&origin=mailchimp');audienceHttpExpect($assistant['status']===200&&str_contains($assistant['body'],'Mailchimp exported summaries'),'Analytics assistant labels its historical source');
audienceHttpExpect($conn->query('SELECT COUNT(*) FROM marketing_campaign_deliveries')->fetch_row()[0]===$jobsBefore&&$conn->query("SELECT GROUP_CONCAT(CONCAT(id,':',email_status) ORDER BY id) FROM marketing_contacts WHERE audience_id=1")->fetch_row()[0]===$contactBefore,'Importing and viewing history change neither delivery jobs nor consent');
audienceHttpExpect($import->analyticsOverview(array_replace($historyWindow,['source_audience'=>'Original example audience']))['totals']['accepted']===1000,'Original audience filters use retained export provenance');
audienceHttpExpect($admin('audience.php?view=analytics&section=history&source_audience=another-account')['status']===400,'Unavailable source audience filter is rejected');
audienceHttpExpect($editor('audience.php?view=analytics&section=history&download=recipients')['status']===400,'History cannot mislabel a native recipient export');
echo 'Mailchimp history HTTP/storage checks passed ('.($checks-$historyStart)." checks).\n";
